import{_ as t,o as a,c as o,ae as i}from"./chunks/framework.RRduUuAx.js";const p=JSON.parse('{"title":"Kilo Gastown Methodology Specification","description":"","frontmatter":{},"headers":[],"relativePath":"plans/KILO_GASTOWN_SPEC.md","filePath":"plans/KILO_GASTOWN_SPEC.md"}'),s={name:"plans/KILO_GASTOWN_SPEC.md"};function n(d,e,r,l,c,h){return a(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="kilo-gastown-methodology-specification" tabindex="-1">Kilo Gastown Methodology Specification <a class="header-anchor" href="#kilo-gastown-methodology-specification" aria-label="Permalink to &quot;Kilo Gastown Methodology Specification&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Kilo Gastown is the agent orchestration and delegation methodology used to coordinate multi-agent development work across the heliosApp ecosystem. It provides a structured system for parallelizing tasks, tracking progress, and managing work through autonomous agents called polecats.</p><p><strong>Version:</strong> 1.0<br><strong>Status:</strong> Active<br><strong>Rig ID:</strong> <code>35903ad7-65d2-489a-bf30-ff95018fd80f</code><br><strong>Town ID:</strong> <code>78a8d430-a206-4a25-96c0-5cd9f5caf984</code></p><hr><h2 id="core-concepts" tabindex="-1">Core Concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core Concepts&quot;">​</a></h2><h3 id="convoys" tabindex="-1">Convoys <a class="header-anchor" href="#convoys" aria-label="Permalink to &quot;Convoys&quot;">​</a></h3><p>A <strong>convoy</strong> is a batch of related work items (beads) that are dispatched together to maximize parallel execution. Convoys enable multiple agents to work simultaneously on different aspects of the same feature or project.</p><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>ID</strong></td><td>Unique identifier (e.g., <code>6d75756c-5831-406f-9d7c-bcd49be2a22a</code>)</td></tr><tr><td><strong>Feature Branch</strong></td><td>Git branch pattern: <code>convoy/&lt;name&gt;/&lt;convoy-id&gt;/head</code></td></tr><tr><td><strong>Status</strong></td><td><code>open</code>, <code>in_progress</code>, <code>landed</code>, or <code>cancelled</code></td></tr><tr><td><strong>Beads</strong></td><td>Contains one or more work items (beads)</td></tr></tbody></table><h3 id="beads" tabindex="-1">Beads <a class="header-anchor" href="#beads" aria-label="Permalink to &quot;Beads&quot;">​</a></h3><p>A <strong>bead</strong> is a single unit of work assigned to an agent. Beads are the atomic tracking entity in Kilo Gastown.</p><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>Type</strong></td><td><code>issue</code> (single task) or <code>convoy</code> (batch of tasks)</td></tr><tr><td><strong>States</strong></td><td><code>open</code> → <code>in_progress</code> → <code>in_review</code> → <code>closed</code></td></tr><tr><td><strong>Assignment</strong></td><td>Assigned to a specific agent via <code>assignee_agent_bead_id</code></td></tr></tbody></table><h3 id="polecats" tabindex="-1">Polecats <a class="header-anchor" href="#polecats" aria-label="Permalink to &quot;Polecats&quot;">​</a></h3><p><strong>Polecats</strong> are autonomous agents that execute assigned beads. Each polecat operates in its own worktree and is responsible for completing its hooked (assigned) bead.</p><hr><h2 id="bead-lifecycle" tabindex="-1">Bead Lifecycle <a class="header-anchor" href="#bead-lifecycle" aria-label="Permalink to &quot;Bead Lifecycle&quot;">​</a></h2><p>Beads follow a defined state machine:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>open → in_progress → in_review → closed</span></span>
<span class="line"><span>  ↓         ↓            ↓</span></span>
<span class="line"><span>blocked   blocked    (rework)</span></span></code></pre></div><table tabindex="0"><thead><tr><th>State</th><th>Description</th></tr></thead><tbody><tr><td><code>open</code></td><td>Work item created, not yet assigned or started</td></tr><tr><td><code>in_progress</code></td><td>Agent is actively working on the bead</td></tr><tr><td><code>in_review</code></td><td>Work submitted for review; awaiting merge</td></tr><tr><td><code>blocked</code></td><td>Work paused due to dependency or issue</td></tr><tr><td><code>closed</code></td><td>Work completed and merged</td></tr></tbody></table><h3 id="lifecycle-transitions" tabindex="-1">Lifecycle Transitions <a class="header-anchor" href="#lifecycle-transitions" aria-label="Permalink to &quot;Lifecycle Transitions&quot;">​</a></h3><ol><li><strong>Assignment</strong> — Bead is assigned to an agent via <code>gt_sling</code> or <code>gt_sling_batch</code></li><li><strong>Hook</strong> — Agent calls <code>gt_prime</code> to receive context and begins work</li><li><strong>Execution</strong> — Agent implements the bead requirements</li><li><strong>Pre-submission Gates</strong> — Agent runs quality gates (<code>task quality</code>)</li><li><strong>Submission</strong> — Agent calls <code>gt_done</code> to push branch and transition to <code>in_review</code></li><li><strong>Review</strong> — Refinery reviews and either merges or requests changes</li><li><strong>Rework</strong> (if requested) — Agent receives feedback, fixes issues, re-submits</li><li><strong>Closure</strong> — Bead marked as <code>closed</code></li></ol><hr><h2 id="delegation-tools" tabindex="-1">Delegation Tools <a class="header-anchor" href="#delegation-tools" aria-label="Permalink to &quot;Delegation Tools&quot;">​</a></h2><h3 id="gt-sling" tabindex="-1">gt_sling <a class="header-anchor" href="#gt-sling" aria-label="Permalink to &quot;gt_sling&quot;">​</a></h3><p>Delegates a single bead to an agent for immediate execution.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gt_sling &lt;bead_id&gt;</span></span></code></pre></div><h3 id="gt-sling-batch" tabindex="-1">gt_sling_batch <a class="header-anchor" href="#gt-sling-batch" aria-label="Permalink to &quot;gt_sling_batch&quot;">​</a></h3><p>Delegates multiple beads (a convoy) to agents for parallel execution.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gt_sling_batch &lt;convoy_id&gt;</span></span></code></pre></div><h3 id="gt-list-convoys" tabindex="-1">gt_list_convoys <a class="header-anchor" href="#gt-list-convoys" aria-label="Permalink to &quot;gt_list_convoys&quot;">​</a></h3><p>Lists all convoys in the rig with their status and progress.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gt_list_convoys</span></span></code></pre></div><h3 id="gt-convoy-status" tabindex="-1">gt_convoy_status <a class="header-anchor" href="#gt-convoy-status" aria-label="Permalink to &quot;gt_convoy_status&quot;">​</a></h3><p>Shows detailed status of a specific convoy including all its beads.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gt_convoy_status &lt;convoy_id&gt;</span></span></code></pre></div><hr><h2 id="merge-modes" tabindex="-1">Merge Modes <a class="header-anchor" href="#merge-modes" aria-label="Permalink to &quot;Merge Modes&quot;">​</a></h2><p>Kilo Gastown supports two merge strategies:</p><h3 id="review-then-land-default" tabindex="-1">Review-Then-Land (Default) <a class="header-anchor" href="#review-then-land-default" aria-label="Permalink to &quot;Review-Then-Land (Default)&quot;">​</a></h3><ol><li>Agent pushes branch and calls <code>gt_done</code></li><li>Bead transitions to <code>in_review</code></li><li>Refinery reviews and merges when ready</li><li>Bead transitions to <code>closed</code></li></ol><h3 id="review-and-merge" tabindex="-1">Review-and-Merge <a class="header-anchor" href="#review-and-merge" aria-label="Permalink to &quot;Review-and-Merge&quot;">​</a></h3><ol><li>Agent pushes branch and calls <code>gt_done</code></li><li>Bead transitions to <code>in_review</code></li><li>Refinery immediately merges (no separate review queue)</li></ol><hr><h2 id="branch-naming-convention" tabindex="-1">Branch Naming Convention <a class="header-anchor" href="#branch-naming-convention" aria-label="Permalink to &quot;Branch Naming Convention&quot;">​</a></h2><p>Feature branches follow the convoy pattern:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>convoy/&lt;project&gt;-kilo-specs-&lt;repo&gt;/&lt;convoy-id&gt;/gt/&lt;agent-name&gt;/&lt;bead-id&gt;</span></span></code></pre></div><p>Example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>convoy/agileplus-kilo-specs-heliosapp/6d75756c/gt/polecat-48/b4803254</span></span></code></pre></div><hr><h2 id="pre-submission-quality-gates" tabindex="-1">Pre-Submission Quality Gates <a class="header-anchor" href="#pre-submission-quality-gates" aria-label="Permalink to &quot;Pre-Submission Quality Gates&quot;">​</a></h2><p>Before calling <code>gt_done</code>, agents must run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">task</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> quality</span></span></code></pre></div><p>This validates:</p><ul><li>Code correctness</li><li>Linting and type checking</li><li>Test passing</li></ul><p>If any gate fails, the agent must fix the issue and re-run until passing.</p><hr><h2 id="integration-with-agileplus" tabindex="-1">Integration with AgilePlus <a class="header-anchor" href="#integration-with-agileplus" aria-label="Permalink to &quot;Integration with AgilePlus&quot;">​</a></h2><p>Kilo Gastown works alongside AgilePlus for comprehensive project tracking:</p><table tabindex="0"><thead><tr><th>Layer</th><th>System</th><th>Tracks</th></tr></thead><tbody><tr><td><strong>Orchestration</strong></td><td>Kilo Gastown</td><td>Agent work, parallelization, delegation</td></tr><tr><td><strong>Execution</strong></td><td>Git branches, commits</td><td>Code changes</td></tr><tr><td><strong>Tracking</strong></td><td>AgilePlus</td><td>Features, work packages, priorities</td></tr></tbody></table><h3 id="cross-reference-pattern" tabindex="-1">Cross-Reference Pattern <a class="header-anchor" href="#cross-reference-pattern" aria-label="Permalink to &quot;Cross-Reference Pattern&quot;">​</a></h3><p>Spec documents include both methodologies:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Migrated from kitty-specs. Tracked in AgilePlus.</span></span></code></pre></div><p>Convoy work is linked via branch naming:</p><ul><li>Branch → Convoy ID → AgilePlus feature</li></ul><hr><h2 id="agent-workflow-summary" tabindex="-1">Agent Workflow Summary <a class="header-anchor" href="#agent-workflow-summary" aria-label="Permalink to &quot;Agent Workflow Summary&quot;">​</a></h2><ol><li><strong>Prime</strong> — Call <code>gt_prime</code> to get context and hooked bead</li><li><strong>Explore</strong> — Understand codebase structure and requirements</li><li><strong>Implement</strong> — Write code, tests, documentation</li><li><strong>Quality Gates</strong> — Run <code>task quality</code> and fix any failures</li><li><strong>Commit &amp; Push</strong> — Make focused commits; push after each</li><li><strong>Checkpoint</strong> — Call <code>gt_checkpoint</code> after milestones</li><li><strong>Done</strong> — Call <code>gt_done</code> with branch name; transitions bead to <code>in_review</code></li></ol><hr><h2 id="cli-reference" tabindex="-1">CLI Reference <a class="header-anchor" href="#cli-reference" aria-label="Permalink to &quot;CLI Reference&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Purpose</th></tr></thead><tbody><tr><td><code>gt_prime</code></td><td>Get context: agent identity, hooked bead, mail, open beads</td></tr><tr><td><code>gt_sling &lt;bead_id&gt;</code></td><td>Delegate single bead</td></tr><tr><td><code>gt_sling_batch &lt;convoy_id&gt;</code></td><td>Delegate all beads in convoy</td></tr><tr><td><code>gt_done --branch &lt;name&gt;</code></td><td>Complete work, push branch, transition to <code>in_review</code></td></tr><tr><td><code>gt_bead_status &lt;bead_id&gt;</code></td><td>Check bead status</td></tr><tr><td><code>gt_checkpoint --data &lt;json&gt;</code></td><td>Save crash-recovery state</td></tr><tr><td><code>gt_list_convoys</code></td><td>List all convoys in rig</td></tr><tr><td><code>gt_mail_send</code></td><td>Send message to another agent</td></tr><tr><td><code>gt_mail_check</code></td><td>Check undelivered mail</td></tr><tr><td><code>gt_escalate</code></td><td>Report issue requiring human intervention</td></tr></tbody></table><hr><h2 id="relationship-with-agents-md" tabindex="-1">Relationship with AGENTS.md <a class="header-anchor" href="#relationship-with-agents-md" aria-label="Permalink to &quot;Relationship with AGENTS.md&quot;">​</a></h2><p>The <code>AGENTS.md</code> file at the repository root is the authoritative agent guidance file for heliosApp, while this spec provides the broader Kilo Gastown methodology context.</p><table tabindex="0"><thead><tr><th>Document</th><th>Scope</th><th>Audience</th></tr></thead><tbody><tr><td><code>KILO_GASTOWN_SPEC.md</code></td><td>Kilo Gastown methodology (this file)</td><td>Cross-project reference</td></tr><tr><td><code>AGENTS.md</code></td><td>heliosApp-specific agent guidance</td><td>All agents working in this rig</td></tr></tbody></table><p>AGENTS.md includes:</p><ul><li>Kilo Gastown identity (rig ID, town ID, convoy)</li><li>Delegation tool usage specific to heliosApp</li><li>heliosApp development commands (<code>bun run typecheck</code>, <code>bun run gates</code>, etc.)</li><li>Stack info and project structure</li><li>Code conventions specific to heliosApp</li><li>Agent behavior rules for this rig</li></ul><p>This spec provides the methodology foundation; AGENTS.md applies it to heliosApp&#39;s specific tooling and conventions.</p><hr><h2 id="related-documentation" tabindex="-1">Related Documentation <a class="header-anchor" href="#related-documentation" aria-label="Permalink to &quot;Related Documentation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Document</th><th>Purpose</th></tr></thead><tbody><tr><td><code>AGENTS.md</code></td><td>heliosApp-specific agent guidance and tooling</td></tr><tr><td><code>AGILEPLUS_SPEC.md</code></td><td>AgilePlus project tracking methodology</td></tr><tr><td><code>PRD.md</code></td><td>Product Requirements Document</td></tr><tr><td><code>CHANGELOG.md</code></td><td>Version history</td></tr><tr><td><code>docs/specs/*/spec.md</code></td><td>Individual technical specifications</td></tr></tbody></table><hr><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>Kilo Gastown provides heliosApp with:</p><ul><li><strong>Parallel execution</strong> — Convoys enable multiple agents to work simultaneously</li><li><strong>Structured delegation</strong> — <code>gt_sling</code> and <code>gt_sling_batch</code> for work distribution</li><li><strong>Bead lifecycle</strong> — Clear state machine from <code>open</code> to <code>closed</code></li><li><strong>Quality enforcement</strong> — Pre-submission gates ensure code quality</li><li><strong>Crash recovery</strong> — Checkpoints enable resume after container restart</li><li><strong>Integration</strong> — Works with AgilePlus for complete project tracking</li></ul>`,84)])])}const u=t(s,[["render",n]]);export{p as __pageData,u as default};
